def compute(vars):
    old_value = vars["v2"]
    new_value = vars["v1"]
    if old_value == 0:
        return None
    change = new_value - old_value
    growth_rate = change / old_value * 100
    return {
        "value": growth_rate,
        "trace": {
            "2012_value": old_value,
            "2013_value": new_value,
            "change": change,
            "growth_rate_percent": growth_rate,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "%"
            }
        }
    }
